#include <stdio.h>

int main(void) {
    int sizes[] = {10, 100, 1000};

    for (int k = 0; k < 3; k++) {
        int n = sizes[k];
        long one = 0, logn = 0, lin = 0, quad = 0;

        one++;                                   /* O(1)     */

        for (int i = n; i > 1; i = i / 2)        /* O(log n) */
            logn++;

        for (int i = 0; i < n; i++)              /* O(n)     */
            lin++;

        for (int i = 0; i < n; i++)              /* O(n^2)   */
            for (int j = 0; j < n; j++)
                quad++;

        printf("n=%4d | O(1)=%ld | O(log n)=%ld | O(n)=%ld | O(n^2)=%ld\n",
               n, one, logn, lin, quad);
    }
    return 0;
}

